package com.alibaba.nacos.consistency.serialize;

import com.alibaba.nacos.api.exception.runtime.NacosDeserializationException;
import org.apache.hc.core5.http.HttpException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.Serializable;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

/**
 * {@link HessianSerializer} unit test.
 *
 * @author Chenhao26
 * @date 2022-08-13
 */
class HessianSerializerTest {

    private HessianSerializer hessianSerializer;

    @BeforeEach
    void setUp() {
        hessianSerializer = new HessianSerializer();
    }

    @Test
    void testSerializerAndDeserialize() {
        String data = "xxx";
        byte[] bytes = hessianSerializer.serialize(data);

        try {
            hessianSerializer.deserialize(bytes);
        } catch (Exception e) {
            assertTrue(e instanceof RuntimeException);
        }

        String res1 = hessianSerializer.deserialize(bytes, String.class);
        assertEquals(data, res1);

        String res2 = hessianSerializer.deserialize(bytes, "java.lang.String");
        assertEquals(data, res2);
    }

    @Test
    void testSerializerAndDeserializeForNotAllowClass() {
        Serializable data = new HttpException();
        byte[] bytes = hessianSerializer.serialize(data);

        try {
            HttpException res = hessianSerializer.deserialize(bytes);
            fail("deserialize success which is not expected");
        } catch (Exception e) {
            assertTrue(e instanceof ClassCastException);
        }

        try {
            HttpException res1 = hessianSerializer.deserialize(bytes, HttpException.class);
        } catch (Exception e) {
            assertTrue(e instanceof NacosDeserializationException);
        }
    }

    @Test
    void testName() {
        assertEquals("Hessian", hessianSerializer.name());
    }

    @Test
    void testDeserializeWithEmptyData() {
        assertNull(hessianSerializer.deserialize(new byte[0], String.class));
    }

    @Test
    void testDeserializeWithType() {
        String data = "testType";
        byte[] bytes = hessianSerializer.serialize(data);
        String result = hessianSerializer.deserialize(bytes, (java.lang.reflect.Type) String.class);
        assertEquals(data, result);
    }

    @Test
    void testDeserializeWithNullData() {
        assertNull(hessianSerializer.deserialize(null, String.class));
    }

    @Test
    void testDeserializeWithInvalidData() {
        byte[] validBytes = hessianSerializer.serialize("test");
        byte[] invalidBytes = new byte[validBytes.length];
        System.arraycopy(validBytes, 0, invalidBytes, 0, validBytes.length);
        invalidBytes[validBytes.length / 2] = (byte) 0xff;
        try {
            hessianSerializer.deserialize(invalidBytes);
            fail("Should throw RuntimeException");
        } catch (RuntimeException e) {
            assertTrue(e.getMessage().contains("IOException"));
        }
    }

    @Test
    void testDeserializeWithInvalidClassName() {
        byte[] bytes = hessianSerializer.serialize("test");
        Object result = hessianSerializer.deserialize(bytes, "com.nonexistent.ClassName");
        assertNull(result);
    }

    @Test
    void testDeserializeWithTypeMismatch() {
        // Serialize a String but try to deserialize as Integer.class
        // This triggers the type mismatch error path which uses String.format
        byte[] bytes = hessianSerializer.serialize("hello");
        try {
            hessianSerializer.deserialize(bytes, Integer.class);
            fail("Should throw NacosDeserializationException");
        } catch (NacosDeserializationException e) {
            // The underlying ClassCastException should have a properly formatted message
            // containing both source and target class names
            ClassCastException cause = (ClassCastException) e.getCause();
            assertNotNull(cause);
            // Correct behavior: String.format should produce
            // "java.lang.String cannot be cast to java.lang.Integer"
            String causeMsg = cause.getMessage();
            assertNotNull(causeMsg);
            assertTrue(causeMsg.contains("java.lang.String"),
                "Cause message should contain source class name: " + causeMsg);
            assertTrue(causeMsg.contains("java.lang.Integer"),
                "Cause message should contain target class name: " + causeMsg);
        } catch (Error e) {
            // If String.format is called as instance method, this will throw NoSuchMethodError at runtime
            fail("Should not throw Error (like NoSuchMethodError): " + e.getMessage());
        }
    }

}

