package com.alibaba.nacos.consistency.snapshot;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link Writer} unit test.
 *
 * @author chenglu
 * @date 2021-07-28 18:50
 */
class WriterTest {

    private Writer writer;

    @BeforeEach
    void setUp() {
        writer = new Writer("test");
    }

    @Test
    void test() {
        assertEquals("test", writer.getPath());

        assertTrue(writer.addFile("a"));

        assertTrue(writer.addFile("b", new LocalFileMeta()));

        assertEquals(2, writer.listFiles().size());

        assertTrue(writer.removeFile("a"));

        assertEquals(1, writer.listFiles().size());
    }

    /**
     * When a caller passes a LocalFileMeta to addFile and then mutates it,
     * the Writer's internal state must remain unchanged. The Writer should
     * store a copy, not the caller's reference.
     */
    @Test
    void testAddFileShouldNotAllowCallerMutation() {
        LocalFileMeta meta = new LocalFileMeta().append("key1", "value1");
        assertTrue(writer.addFile("x", meta));

        // Mutate the original meta after adding it
        meta.append("key2", "value2");

        // The stored meta should NOT have key2 — caller mutations should not affect it
        LocalFileMeta stored = writer.listFiles().get("x");
        assertEquals("value1", stored.get("key1"));
        assertEquals(null, stored.get("key2"), "Caller-side mutation of LocalFileMeta should not affect stored state");
    }
}

